    L1: 6.0, L2: 1.2, L3: 1.6, L4: 5.4, H: null, y_t: 0.0,
    M: 8000.0, m: 60.0, m_b: 500.0, I_b: null, L_CM: null, I_c: 0.0, m_f: 0.0,
    th0: rad(40.0), ps0: 0.0, ph0: null, start: 'trough', sling: true, ground_check: true,
    sling_rigid: false,
    d: null, rho_s: 2700.0, C_d: 0.40, cd_model: 'const', rho_a: 1.225, nu_a: 1.5e-5, g: 9.81,
    y_target: 0.0, drag_flight: true, drag_sling: true, drag_phase1: true, alpha_s: 1.0,
    C_d_sling: null,
    mu_a: 0.0, r_a: 0.0, mu_h: 0.0, r_h: 0.0, mu_t: 0.0, C_rr: 0.0, mu_g: 0.0, Cd_beam: 0.0,
    D_b: 0.0, mu_static_factor: 1.25,
    release: 'ideal', beta: rad(90.0), mu_p: 0.0, alpha_r: rad(40.0), t_r: null,
    theta_rel: rad(135.0), ideal_objective: 'axle',
    N_p: 0, f_p0: 0.0, v_p0: 4.0, tau_p: 0.1, s_p: 1.0e9, alpha_p: 0.0, F_p_const: null,
    t_max: 6.0, t_after: 1.5, rtol: 1e-10, atol: 1e-10, v_s: 1e-3, n_fric_iter: 3,
    baumgarte: 20.0, delta_max: rad(170.0),
