      H: H_eff(mc), I_b: I_b_eff(mc), L_CM: L_CM_eff(mc), d: d_eff(mc), dh_cw: dh_cw(mc),
      L_b: mc.L1 + mc.L2, ratio: mc.M / mc.m, dU_H: dU_H(mc),
