  const zeros = (n) => new Array(n).fill(0);

  // ------------------------------------------------------------------ dynamics (dynamics.py)
  const LOSS_KEYS = ['axle', 'hinge', 'trough', 'roll', 'guide', 'drag', 'beam_drag', 'crew'];
  const NW = LOSS_KEYS.length;
