      this.projPt = this.hasSling ? 'p' : 'S';
      this.m_proj = projectileOn ? mc.m : 0.0;
      this.e_p = [Math.sin(mc.alpha_p), -Math.cos(mc.alpha_p)];
      this.K0 = null;
      this.hasFriction = [mc.mu_a * mc.r_a, mc.mu_h * mc.r_h, mc.mu_t, mc.C_rr, mc.mu_g].some((v) => v > 0);
      const d = d_eff(mc);
      this.A_sling = mc.alpha_s * PI * d * d / 4.0;
